    fn rendered_client_view_text(
        app: &App,
        client_view: &ClientViewState,
        width: u16,
        height: u16,
    ) -> String {
        let backend = ratatui::backend::TestBackend::new(width, height);
        let mut terminal = ratatui::Terminal::new(backend).expect("test backend");
        terminal
            .draw(|frame| {
                crate::ui::render_with_runtime_registry_for_view(
                    &app.state,
                    client_view,
                    &app.terminal_runtimes,
                    frame,
                )
            })
            .expect("render client view");
        let buffer = terminal.backend().buffer();
        let mut text = String::new();
        for y in 0..height {
            for x in 0..width {
                text.push_str(buffer[(x, y)].symbol());
            }
            text.push('\n');
        }
        text
    }

    fn rendered_client_view_text_point(
        app: &App,
        client_view: &ClientViewState,
        text: &str,
        width: u16,
        height: u16,
    ) -> (u16, u16) {
        let backend = ratatui::backend::TestBackend::new(width, height);
        let mut terminal = ratatui::Terminal::new(backend).expect("test backend");
        terminal
            .draw(|frame| {
                crate::ui::render_with_runtime_registry_for_view(
                    &app.state,
                    client_view,
                    &app.terminal_runtimes,
                    frame,
                )
            })
            .expect("render client view");
        let buffer = terminal.backend().buffer();
        let symbols = text.chars().map(|ch| ch.to_string()).collect::<Vec<_>>();

        for y in 0..height {
            for x in 0..=width.saturating_sub(symbols.len() as u16) {
                if symbols
                    .iter()
                    .enumerate()
                    .all(|(idx, symbol)| buffer[(x + idx as u16, y)].symbol() == symbol.as_str())
                {
                    return (x, y);
                }
            }
        }

        panic!("rendered client view text not found: {text}");
    }

    fn mobile_switcher_point_for_target(
        app: &App,
        client_view: &ClientViewState,
        target: crate::ui::MobileSwitcherTarget,
    ) -> (u16, u16) {
        let areas = crate::ui::mobile_switcher_areas_for_view(&app.state, client_view);
        for row in areas.viewport.y..areas.viewport.y + areas.viewport.height {
            for column in areas.viewport.x..areas.viewport.x + areas.viewport.width {
                if crate::ui::mobile_switcher_target_at_for_view(
                    &app.state,
                    &app.terminal_runtimes,
                    client_view,
                    column,
                    row,
                )
                .as_ref()
                    == Some(&target)
                {
                    return (column, row);
                }
            }
        }

        panic!("mobile switcher target not visible: {target:?}");
    }

    fn rendered_text_point_at_or_after_row(
        app: &App,
        text: &str,
        min_row: u16,
        width: u16,
        height: u16,
    ) -> (u16, u16) {
        let backend = ratatui::backend::TestBackend::new(width, height);
        let mut terminal = ratatui::Terminal::new(backend).expect("test backend");
        terminal
            .draw(|frame| crate::ui::render(&app.state, frame))
            .expect("render app");
        let buffer = terminal.backend().buffer();
        let symbols = text.chars().map(|ch| ch.to_string()).collect::<Vec<_>>();
        let text_width = symbols.len() as u16;

        for y in min_row..height {
            for x in 0..=width.saturating_sub(text_width) {
                if symbols
                    .iter()
                    .enumerate()
                    .all(|(idx, ch)| buffer[(x + idx as u16, y)].symbol() == ch.as_str())
                {
                    return (x, y);
                }
            }
        }

        panic!("rendered text not found: {text}");
    }

