    #[test]
    fn github_palette_escape_and_scope_invalidation_stay_client_local() {
        let mut app = test_app();
        app.state.workspaces = vec![Workspace::test_new("one"), Workspace::test_new("two")];
        app.state.active = Some(0);
        app.state.mode = Mode::Terminal;
        let scope = crate::github::ResolvedGithubScope {
            repositories: Vec::new(),
            organization: None,
        };
        let mut first = ClientViewState::from_default_client_state(&app.state);
        let mut second = ClientViewState::from_default_client_state(&app.state);
        for (index, view) in [(0, &mut first), (1, &mut second)] {
            view.active_workspace = Some(index);
            view.github_workspace_id = Some(app.state.workspaces[index].id.clone());
            view.github_scope_settings =
                Some((crate::github::GithubRepositoryScope::Automatic, None));
            view.github = Some(crate::github::screen::GithubScreen::new(
                scope.clone(),
                "GitHub".into(),
            ));
            view.mode = Mode::CommandPalette;
        }
        app.route_client_events_for_view(
            &mut first,
            vec![raw_key(
                KeyCode::Esc,
                KeyModifiers::empty(),
                KeyEventKind::Press,
            )],
            false,
        );
        assert_eq!(first.mode, Mode::Github);
        assert_eq!(second.mode, Mode::CommandPalette);
        app.state.workspaces[0].github_scope =
            crate::github::GithubRepositoryScope::GroupOrganization;
        assert!(app.pump_github_for_view(&mut first));
        assert!(first.github.is_none());
        assert_eq!(first.mode, Mode::Terminal);
        assert!(second.github.is_some());
        assert_eq!(second.mode, Mode::CommandPalette);
        assert!(app.state.request_open_project_command.is_none());
        app.close_github_for_view(&mut second);
    }

    #[test]
    fn host_integration_updates_ignore_superseded_requests() {
        let mut app = test_app();
        let host_id = crate::execution_host::ExecutionHostId::new("ssh:workbox:1").unwrap();
        let current_request = crate::execution_host::protocol::RequestId::new(2);
        app.state
            .host_integration_request_ids
            .insert(host_id.clone(), current_request);
        let result = || crate::integration::host::HostIntegrationResult {
            snapshot: crate::integration::host::HostIntegrationSnapshot {
                entries: Vec::new(),
            },
            messages: vec!["installed on workbox".to_string()],
        };

        assert!(!app.apply_host_integration_update(
            host_id.clone(),
            crate::execution_host::protocol::RequestId::new(1),
            Ok(result()),
        ));
        assert!(!app
            .state
            .host_integration_observations
            .contains_key(&host_id));

        assert!(app.apply_host_integration_update(host_id.clone(), current_request, Ok(result()),));
        assert!(matches!(
            app.state.host_integration_observations.get(&host_id),
            Some(crate::integration::host::HostIntegrationObservation::Ready(
                _
            ))
        ));
        assert_eq!(
            app.state
                .host_integration_install_messages
                .get(&host_id)
                .map(Vec::as_slice),
            Some(["installed on workbox".to_string()].as_slice())
        );
    }
