    #[test]
    fn reload_config_updates_live_state_and_future_client_defaults() {
        let _guard = config_env_lock().lock().unwrap();
        let path = temp_config_path("reload-config-success");
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(
            &path,
            "[terminal]\ndefault_shell = \"nu\"\nshell_mode = \"non_login\"\nnew_cwd = \"home\"\n[keys]\nnew_workspace = \"prefix+g\"\nprefix = \"ctrl+a\"\n[update]\nversion_check = false\nmanifest_check = false\n[ui]\ncopy_on_select = false\nredraw_on_focus_gained = false\nright_click_passthrough_modifier = \"ctrl\"\n[ui.sidebar]\ninitial_state = \"collapsed\"\ninitial_agent_scope = \"current\"\n[ui.toast]\ndelivery = \"gardn\"\n",
        )
        .unwrap();
        let _config_path_env =
            crate::config::TestEnvVar::set(crate::config::CONFIG_PATH_ENV_VAR, &path);

        let mut app = test_app();
        app.state.workspaces = vec![Workspace::test_new("selection")];
        app.next_auto_update_check = Some(Instant::now());
        app.next_agent_manifest_update_check = Some(Instant::now());
        let pane_id = app.state.workspaces[0].tabs[0].root_pane;
        app.state.selection = Some(crate::selection::Selection::anchor(pane_id, 0, 0, None));
        let report = app.reload_config();

        assert_eq!(report.status, crate::config::ConfigReloadStatus::Applied);
        assert_eq!(app.state.prefix_code, KeyCode::Char('a'));
        assert_eq!(app.state.prefix_mods, KeyModifiers::CONTROL);
        assert!(app
            .state
            .keybinds
            .new_workspace
            .matches_prefix(&KeyEvent::new(KeyCode::Char('g'), KeyModifiers::empty())));
        assert_eq!(
            app.state.toast_config.delivery,
            crate::config::ToastDelivery::Gardn
        );
        assert_eq!(
            app.state.agent_panel_scope,
            state::AgentPanelScope::AllWorkspaces
        );
        assert_eq!(
            app.state.sidebar_config.initial_agent_scope,
            crate::config::AgentPanelScopeConfig::Current
        );
        assert!(!app.default_client_view.sidebar_collapsed);
        assert_eq!(
            app.default_client_view.agent_panel_scope,
            state::AgentPanelScope::AllWorkspaces
        );
        let next_client = ClientViewState::for_new_client(&app.state);
        assert!(next_client.sidebar_collapsed);
        assert_eq!(
            next_client.agent_panel_scope,
            state::AgentPanelScope::CurrentWorkspace
        );
        assert!(!app.state.redraw_on_focus_gained);
        assert_eq!(
            app.state.right_click_passthrough_modifiers,
            Some(KeyModifiers::CONTROL)
        );
        assert!(!app.state.copy_on_select);
        assert!(app.state.selection.is_some());
        assert!(app.state.request_client_config_reload);
        assert_eq!(app.state.default_shell, "nu");
        assert_eq!(
            app.state.shell_mode,
            crate::config::ShellModeConfig::NonLogin
        );
        assert_eq!(
            app.state.new_terminal_cwd,
            crate::config::NewTerminalCwdConfig::Home
        );
        assert!(!app.update_version_check_enabled);
        assert!(!app.update_manifest_check_enabled);
        assert!(app.next_auto_update_check.is_none());
        assert!(app.next_agent_manifest_update_check.is_none());
        assert!(app.state.config_diagnostic.is_none());
        let toast = app.state.toast.as_ref().unwrap();
        assert_eq!(toast.kind, crate::app::state::ToastKind::UpdateInstalled);
        assert_eq!(toast.title, "Reloaded Config");
        assert_eq!(toast.context, "Using config.toml");

        let _ = std::fs::remove_dir_all(path.parent().unwrap());
    }

