    #[tokio::test]
    async fn route_client_events_for_view_right_click_passthrough_forwards_gesture_without_context_menu(
    ) {
        let mut app = test_app();
        let server_workspace = Workspace::test_new("server");
        let client_workspace = Workspace::test_new("client");
        let server_pane = server_workspace.tabs[0].root_pane;
        let pane_id = client_workspace.tabs[0].root_pane;
        app.state.workspaces = vec![server_workspace, client_workspace];
        app.state.ensure_test_terminals();
        app.state.active = Some(0);
        app.state.selected = 0;
        app.state.mode = Mode::Terminal;
        app.state.mouse_capture = true;
        app.state.right_click_passthrough_modifiers = Some(KeyModifiers::CONTROL);
        app.state.selection = Some(crate::selection::Selection::anchor(server_pane, 0, 0, None));
        app.state.drag = Some(state::DragState {
            target: state::DragTarget::SidebarDivider,
        });
        app.default_client_view = ClientViewState::from_default_client_state(&app.state);

        app.state.active = Some(1);
        app.state.selected = 1;
        let mut client = ClientViewState::from_default_client_state(&app.state);
        app.state.active = Some(0);
        app.state.selected = 0;
        client.set_tab_control(ClientTabControl::Controlling { epoch: 1 });
        client.selection = Some(crate::selection::Selection::anchor(pane_id, 0, 0, None));
        client.drag = Some(state::DragState {
            target: state::DragTarget::SidebarDivider,
        });
        client.reconcile(&app.state);
        let other_client = ClientViewState::from_default_client_state(&app.state);
        compute_client_view(&app, &mut client, ratatui::layout::Rect::new(0, 0, 120, 30));
        let pane = client
            .computed
            .pane_infos
            .iter()
            .find(|pane| pane.id == pane_id)
            .expect("client pane should be visible")
            .clone();
        let (runtime, mut rx) = TerminalRuntime::test_with_channel_and_screen_bytes(
            pane.inner_rect.width.max(1),
            pane.inner_rect.height.max(1),
            b"\x1b[?1002h\x1b[?1006h",
        );
        app.state.workspaces[1].insert_test_runtime(pane_id, runtime);

        let (col, row) =
            screen_point_for_client_canvas(&client, pane.inner_rect.x + 2, pane.inner_rect.y + 3);
        let (drag_col, drag_row) =
            screen_point_for_client_canvas(&client, pane.inner_rect.x + 3, pane.inner_rect.y + 4);
        app.route_client_events_for_view(
            &mut client,
            vec![
                raw_mouse_with_modifiers(
                    crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Right),
                    col,
                    row,
                    KeyModifiers::CONTROL,
                ),
                raw_mouse_with_modifiers(
                    crossterm::event::MouseEventKind::Drag(crossterm::event::MouseButton::Right),
                    drag_col,
                    drag_row,
                    KeyModifiers::CONTROL,
                ),
                raw_mouse_with_modifiers(
                    crossterm::event::MouseEventKind::Up(crossterm::event::MouseButton::Right),
                    drag_col,
                    drag_row,
                    KeyModifiers::CONTROL,
                ),
            ],
            true,
        );

        assert_eq!(
            rx.try_recv()
                .expect("right mouse down should be forwarded without modifiers"),
            bytes::Bytes::from_static(b"\x1b[<2;3;4M")
        );
        assert_eq!(
            rx.try_recv()
                .expect("right mouse drag should be forwarded without modifiers"),
            bytes::Bytes::from_static(b"\x1b[<34;4;5M")
        );
        assert_eq!(
            rx.try_recv()
                .expect("right mouse up should be forwarded without modifiers"),
            bytes::Bytes::from_static(b"\x1b[<2;4;5m")
        );
        assert!(rx.try_recv().is_err());
        assert!(client.context_menu.is_none());
        assert_eq!(client.mode, Mode::Terminal);
        assert!(client.selection.is_none());
        assert!(client.drag.is_none());
        assert!(other_client.context_menu.is_none());
        assert_eq!(other_client.mode, Mode::Terminal);
        assert!(app.state.context_menu.is_none());
        assert_eq!(app.state.active, Some(0));
        assert_eq!(app.state.selected, 0);
        assert_eq!(app.state.mode, Mode::Terminal);
        assert!(app.state.selection.is_some());
        assert!(app.state.drag.is_some());
        assert!(app.state.right_click_passthrough.is_none());
    }

    #[tokio::test]
    async fn route_client_events_for_view_dragging_pane_split_updates_invoking_client_tab_layout() {
        fn root_split_ratio(workspace: &Workspace, tab_idx: usize) -> f32 {
            let crate::layout::Node::Split { ratio, .. } = workspace.tabs[tab_idx].layout.root()
            else {
                panic!("test fixture should use a split layout");
            };
            *ratio
        }

        let mut app = test_app();
        let mut server_workspace = Workspace::test_new("server");
        server_workspace.test_split(ratatui::layout::Direction::Horizontal);

        let mut client_workspace = Workspace::test_new("client");
        client_workspace.test_split(ratatui::layout::Direction::Horizontal);
        let client_active_tab = client_workspace.test_add_tab(Some("logs"));
        client_workspace.switch_tab(client_active_tab);
        client_workspace.test_split(ratatui::layout::Direction::Horizontal);
        client_workspace.switch_tab(0);

        app.state.workspaces = vec![server_workspace, client_workspace];
        app.state.ensure_test_terminals();
        app.state.active = Some(0);
        app.state.selected = 0;
        app.state.mode = Mode::Terminal;
        app.state.mouse_capture = true;
        app.default_client_view = ClientViewState::from_default_client_state(&app.state);

        let client_workspace_id = app.state.workspaces[1].id.clone();
        let server_ratio_before = root_split_ratio(&app.state.workspaces[0], 0);
        let client_inactive_tab_ratio_before = root_split_ratio(&app.state.workspaces[1], 0);
        let client_active_tab_ratio_before =
            root_split_ratio(&app.state.workspaces[1], client_active_tab);
        let other_client = ClientViewState::from_default_client_state(&app.state);
        let mut client = ClientViewState::from_default_client_state(&app.state);
        client.set_tab_control(ClientTabControl::Controlling { epoch: 1 });
        client.active_workspace = Some(1);
        client.selected_workspace = 1;
        client
            .active_tabs
            .insert(client_workspace_id.clone(), client_active_tab);
        client.reconcile(&app.state);

        compute_client_view(&app, &mut client, ratatui::layout::Rect::new(0, 0, 140, 32));
        let border = client
            .computed
            .split_borders
            .iter()
            .find(|border| border.direction == ratatui::layout::Direction::Horizontal)
            .cloned()
            .expect("client active tab should render a horizontal pane split border");
        let drag_row_canvas = border.area.y + border.area.height / 2;
        let drag_col_canvas =
            (border.pos + 10).min(border.area.x + border.area.width.saturating_sub(1));
        let (border_col, border_row) =
            screen_point_for_client_canvas(&client, border.pos, drag_row_canvas);
        let (drag_col, drag_row) =
            screen_point_for_client_canvas(&client, drag_col_canvas, drag_row_canvas);

        app.route_client_events_for_view(
            &mut client,
            vec![
                raw_mouse(
                    crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                    border_col,
                    border_row,
                ),
                raw_mouse(
                    crossterm::event::MouseEventKind::Drag(crossterm::event::MouseButton::Left),
                    drag_col,
                    drag_row,
                ),
                raw_mouse(
                    crossterm::event::MouseEventKind::Up(crossterm::event::MouseButton::Left),
                    drag_col,
                    drag_row,
                ),
            ],
            true,
        );

        assert_ne!(
            root_split_ratio(&app.state.workspaces[1], client_active_tab),
            client_active_tab_ratio_before,
            "dragging a rendered pane split in a client view should resize that client's active tab"
        );
        assert_eq!(
            root_split_ratio(&app.state.workspaces[1], 0),
            client_inactive_tab_ratio_before,
            "the client workspace tab that is not active in the invoking client should not resize"
        );
        assert_eq!(
            root_split_ratio(&app.state.workspaces[0], 0),
            server_ratio_before,
            "the server/global active workspace should not receive the client-view split drag"
        );
        assert_eq!(app.state.active, Some(0));
        assert_eq!(app.state.selected, 0);
        assert!(app.state.drag.is_none());
        assert!(client.drag.is_none());
        assert_eq!(
            other_client.active_tab_for_workspace(&client_workspace_id),
            Some(0)
        );
    }

