    #[tokio::test]
    async fn route_client_events_for_view_mobile_agent_strip_focuses_client_locally() {
        let mut app = test_app();
        app.state.workspaces = vec![Workspace::test_new("one"), Workspace::test_new("two")];
        app.state.ensure_test_terminals();
        app.state.active = Some(0);
        app.state.selected = 0;
        app.state.mode = Mode::Terminal;
        let pane_id = app.state.workspaces[1].tabs[0].root_pane;
        let terminal_id = app.state.workspaces[1].tabs[0].panes[&pane_id]
            .attached_terminal_id
            .clone();
        app.state
            .terminals
            .get_mut(&terminal_id)
            .expect("agent terminal")
            .set_detected_state(Some(Agent::Codex), AgentState::Working);

        let area = ratatui::layout::Rect::new(0, 0, 44, 20);
        let shared_scope = app.state.agent_panel_scope;
        let mut client = ClientViewState::from_default_client_state(&app.state);
        let other_client = ClientViewState::from_default_client_state(&app.state);
        compute_client_view(&app, &mut client, area);

        let strip = crate::ui::mobile_agent_strip_rect(client.computed.mobile_header_rect);
        let (column, row) = (strip.x + 2, strip.y);
        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                column,
                row,
            )],
            true,
        );
        assert!(client.mobile_agents_expanded);
        assert_eq!(client.mode, Mode::Navigate);
        assert!(!app.state.mobile_agents_expanded);
        assert!(!other_client.mobile_agents_expanded);
        let expanded = crate::ui::mobile_switcher_areas_for_view(&app.state, &client);
        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                expanded.agent_scope.x + 1,
                expanded.agent_scope.y,
            )],
            true,
        );
        assert_eq!(client.mode, Mode::AgentMenu);
        let scope_menu = app.client_view_agent_menu_rect(&client);
        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                scope_menu.x + 2,
                scope_menu.y + 4,
            )],
            true,
        );
        assert_eq!(
            client.agent_panel_scope,
            state::AgentPanelScope::CurrentGroup
        );
        assert_eq!(app.state.agent_panel_scope, shared_scope);
        assert_eq!(other_client.agent_panel_scope, shared_scope);
        assert_eq!(client.mode, Mode::Navigate);
        assert!(client.mobile_agents_expanded);

        let (column, row) = mobile_switcher_point_for_target(
            &app,
            &client,
            crate::ui::MobileSwitcherTarget::Agent {
                ws_idx: 1,
                tab_idx: 0,
                pane_id,
            },
        );
        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                column,
                row,
            )],
            true,
        );

        assert_eq!(client.active_workspace, Some(1));
        assert_eq!(
            client.focused_pane_for_workspace(&app.state, 1),
            Some((0, pane_id))
        );
        assert_eq!(client.mode, Mode::Terminal);
        assert!(!client.mobile_agents_expanded);
        assert_eq!(app.state.active, Some(0));
        assert_eq!(other_client.active_workspace, Some(0));
    }

    #[tokio::test]
    async fn route_client_events_for_view_mobile_switcher_scrolls_and_click_outside_closes() {
        let mut app = test_app();
        app.state.workspaces = (0..12)
            .map(|idx| Workspace::test_new(&format!("workspace-{idx}")))
            .collect();
        let group_id = app.state.groups[0].id.clone();
        for workspace in &mut app.state.workspaces {
            workspace.group_id = group_id.clone();
        }
        app.state.ensure_test_terminals();
        app.state.active = Some(0);
        app.state.selected = 0;
        app.state.mode = Mode::Terminal;
        app.state.mouse_capture = true;

        let area = ratatui::layout::Rect::new(0, 0, 44, 10);
        let mut client = ClientViewState::from_default_client_state(&app.state);
        client.mode = Mode::Navigate;
        client.mobile_switcher_level = state::MobileSwitcherLevel::Workspaces { group_idx: 0 };
        compute_client_view(&app, &mut client, area);
        assert_eq!(client.computed.layout, state::ViewLayout::Mobile);
        let rendered = rendered_client_view_text(&app, &client, area.width, area.height);
        assert!(
            rendered.contains("workspace-0")
                && rendered.contains("workspace-4")
                && !rendered.contains("workspace-5"),
            "test fixture should render the bounded, scrollable space dropdown:\n{rendered}"
        );
        assert!(
            crate::ui::mobile_switcher_max_scroll_for_view(
                &app.state,
                &app.terminal_runtimes,
                &client
            ) >= 2,
            "test fixture should make the mobile switcher scrollable"
        );
        let areas = crate::ui::mobile_switcher_areas_for_view(&app.state, &client);

        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::ScrollDown,
                areas.viewport.x + 2,
                areas.viewport.y,
            )],
            true,
        );
        let scroll_after_wheel = client.mobile_switcher_scroll;

        let terminal = client.computed.terminal_area;
        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                terminal.x + 1,
                terminal.y + terminal.height.saturating_sub(1),
            )],
            true,
        );

        assert_eq!(scroll_after_wheel, 2);
        assert_eq!(client.mode, Mode::Terminal);
        assert_eq!(app.state.mode, Mode::Terminal);
        assert_eq!(app.state.mobile_switcher_scroll, 0);
    }

