    #[test]
    fn route_client_events_for_view_keybind_help_filter_stays_client_local() {
        let mut app = test_app();
        app.state.workspaces = vec![Workspace::test_new("test")];
        app.state.ensure_test_terminals();
        app.state.active = Some(0);
        app.state.selected = 0;
        app.state.mode = Mode::Terminal;

        let mut client = ClientViewState::from_default_client_state(&app.state);
        client.mode = Mode::KeybindHelp;
        compute_client_view(&app, &mut client, ratatui::layout::Rect::new(0, 0, 120, 30));

        app.route_client_events_for_view(
            &mut client,
            vec![crate::raw_input::RawInputEvent::TextCommit(
                crate::input::TextCommit::new("/zzzz-no-such-bind"),
            )],
            true,
        );

        assert!(client.keybind_help.search_focused);
        assert_eq!(client.keybind_help.query, "zzzz-no-such-bind");
        assert!(app.state.keybind_help.query.is_empty());
        assert_eq!(app.state.mode, Mode::Terminal);

        let lines = crate::ui::keybind_help_lines(&app.state, 70, &client.keybind_help.query);
        let rendered = lines
            .into_iter()
            .flat_map(|(_, line)| line.spans)
            .map(|span| span.content.into_owned())
            .collect::<String>();
        assert!(rendered.contains("no matching keybinds"));

        app.route_client_events_for_view(
            &mut client,
            vec![raw_key(
                KeyCode::Esc,
                KeyModifiers::empty(),
                KeyEventKind::Press,
            )],
            true,
        );
        assert_eq!(client.mode, Mode::KeybindHelp);
        assert!(!client.keybind_help.search_focused);
        assert!(client.keybind_help.query.is_empty());

        app.route_client_events_for_view(
            &mut client,
            vec![raw_key(
                KeyCode::Esc,
                KeyModifiers::empty(),
                KeyEventKind::Press,
            )],
            true,
        );
        assert_eq!(client.mode, Mode::Terminal);
    }

    #[test]
    fn route_client_events_for_view_release_notes_mouse_scroll_and_close_stay_client_local() {
        let mut app = test_app();
        app.state.workspaces = vec![Workspace::test_new("test")];
        app.state.ensure_test_terminals();
        app.state.active = Some(0);
        app.state.selected = 0;
        app.state.mode = Mode::Terminal;
        app.state.mouse_capture = true;

        let mut client = ClientViewState::from_default_client_state(&app.state);
        let body = (0..80)
            .map(|idx| {
                format!(
                    "### Release note {idx}\n- Client overlay mouse routing regression line {idx}"
                )
            })
            .collect::<Vec<_>>()
            .join("\n");
        client.mode = Mode::ReleaseNotes;
        client.release_notes = Some(state::ReleaseNotesState {
            version: "test-release".into(),
            body,
            scroll: 0,
            preview: false,
        });
        compute_client_view(&app, &mut client, ratatui::layout::Rect::new(0, 0, 120, 30));
        assert!(client
            .release_notes
            .as_ref()
            .is_some_and(|notes| notes.scroll == 0));
        let popup = crate::ui::centered_popup_rect(
            client.screen_rect(),
            crate::ui::RELEASE_NOTES_MODAL_SIZE.0,
            crate::ui::RELEASE_NOTES_MODAL_SIZE.1,
        )
        .expect("release notes popup");
        let scroll_col = popup.x + popup.width / 2;
        let scroll_row = popup.y + popup.height / 2;

        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::ScrollDown,
                scroll_col,
                scroll_row,
            )],
            true,
        );

        assert!(client.release_notes.as_ref().unwrap().scroll > 0);
        assert_eq!(client.mode, Mode::ReleaseNotes);
        assert_eq!(app.state.mode, Mode::Terminal);
        assert!(app.state.release_notes.is_none());

        let inner = ratatui::layout::Rect::new(
            popup.x + 1,
            popup.y + 1,
            popup.width.saturating_sub(2),
            popup.height.saturating_sub(2),
        );
        let close = crate::ui::release_notes_close_button_rect(ratatui::layout::Rect::new(
            inner.x,
            inner.y,
            inner.width,
            1,
        ));

        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                close.x + close.width / 2,
                close.y,
            )],
            true,
        );

        assert_eq!(client.mode, Mode::Terminal);
        assert_eq!(app.state.mode, Mode::Terminal);
        assert!(app.state.release_notes.is_none());
    }

