    #[tokio::test]
    async fn route_client_events_for_view_context_new_tab_creates_shared_tab() {
        for (case, kind) in [
            (
                "new tab button",
                state::ContextMenuKind::NewTabButton {
                    ws_idx: 0,
                    project_commands: state::ProjectCommandAvailability::NONE,
                },
            ),
            (
                "workspace",
                state::ContextMenuKind::Workspace {
                    ws_idx: 0,
                    project_commands: state::ProjectCommandAvailability::NONE,
                },
            ),
        ] {
            let mut app = test_app();
            app.state.workspaces = vec![Workspace::test_new("shell")];
            app.state.ensure_test_terminals();
            app.state.active = Some(0);
            app.state.selected = 0;
            app.state.mode = Mode::Terminal;
            app.state.mouse_capture = true;
            app.state.prompt_new_tab_name = false;

            let mut client = ClientViewState::from_default_client_state(&app.state);
            client.context_menu = Some(state::ContextMenuState {
                kind,
                x: 4,
                y: 4,
                list: state::ModalListState::new(1),
            });
            client.mode = Mode::ContextMenu;
            compute_client_view(&app, &mut client, ratatui::layout::Rect::new(0, 0, 120, 30));
            let menu = context_menu_rect_for_client_view(&app, &client);

            app.route_client_events_for_view(
                &mut client,
                vec![raw_mouse(
                    crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                    menu.x + 2,
                    menu.y + 2,
                )],
                true,
            );

            assert!(
                app.state.request_new_tab,
                "{case} queued a shared tab request"
            );
            assert_eq!(
                app.state.workspaces[0].tabs.len(),
                1,
                "{case} defers creation to the app cycle"
            );

            assert!(
                app.process_deferred_workspace_requests(),
                "{case} app cycle processes queued tab request"
            );
            assert!(
                !app.state.request_new_tab,
                "{case} consumes the tab request"
            );
            assert_eq!(
                app.state.workspaces[0].tabs.len(),
                2,
                "{case} creates a tab through the normal app cycle"
            );
            assert_eq!(
                app.state.workspaces[0].active_tab_index(),
                1,
                "{case} focuses the created shared tab"
            );
        }
    }

    #[test]
    fn route_client_events_for_view_navigator_hover_and_click_stay_client_local() {
        let mut app = test_app();
        app.state.workspaces = vec![Workspace::test_new("first"), Workspace::test_new("second")];
        app.state.ensure_test_terminals();
        app.state.active = Some(0);
        app.state.selected = 0;
        app.state.mode = Mode::Terminal;
        app.state.mouse_capture = true;

        let mut client = ClientViewState::from_default_client_state(&app.state);
        client.mode = Mode::Navigator;
        client.navigator.list = state::ModalListState::hidden(0);
        client
            .navigator
            .expanded_groups
            .insert(app.state.groups[0].id.clone());
        compute_client_view(&app, &mut client, ratatui::layout::Rect::new(0, 0, 120, 30));
        let body = app.client_view_navigator_body_rect(&client);
        let second_workspace_index = app
            .navigator_view_rows(&client)
            .iter()
            .position(|row| matches!(row.target, state::NavigatorTarget::Workspace { ws_idx: 1 }))
            .expect("second workspace row");
        let second_workspace_row = body.y + second_workspace_index as u16;
        let row_col = body.x + 5;

        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Moved,
                row_col,
                second_workspace_row,
            )],
            true,
        );
        assert_eq!(client.navigator.list.selected, 0);
        assert_eq!(
            client.navigator.list.visible(),
            Some(second_workspace_index)
        );

        app.route_client_events_for_view(
            &mut client,
            vec![raw_mouse(
                crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left),
                row_col,
                second_workspace_row,
            )],
            true,
        );
        assert_eq!(client.active_workspace, Some(1));
        assert_eq!(client.mode, Mode::Terminal);
        assert_eq!(
            app.state.active,
            Some(0),
            "navigator click remains local to the invoking client"
        );
    }

